import { useState } from "react";

const HARD_CODED_VALUES = {
  heartRateRange: "Comfort: 60-100, Monitor: 100-120, Stop exercise: >120",
  exerciseList: [
    "Bike (New Step)",
    "Cable row (Techno)",
    "Chest press (Hammer)",
    "Leg press (Techno)",
    "Step up (Stairs)",
    "Hip flexion (Parallel bars)",
    "Shoulder raise (Dumbells)"
  ],
  repsTime: [
    "15 min",
    "10 reps (bilateral)",
    "10 reps (bilateral)",
    "10 reps (unilateral)",
    "10 reps (unilateral)",
    "15 reps (unilateral)",
    "15 reps (unilateral)",
    "15 reps (unilateral)"
  ],
  weightIntensity: ["L1 - 5 min", "L2 - 10 min", "40 lbs", "30 lbs", "80 lbs", "NA", "NA", "5 lbs"]
};

function App() {
  const [key, setKey] = useState("");
  const [user, setUser] = useState(null);
  const [error, setError] = useState("");

  const login = async () => {
    const res = await fetch("http://localhost:5000/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ key })
    });
    const data = await res.json();
    if (!res.ok) {
      setError(data.message);
      return;
    }
    setUser(data.user);
    setError("");
  };

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h1>Key Login</h1>
        <input
          value={key}
          onChange={(e) => setKey(e.target.value)}
          placeholder="Enter key"
        />
        <button onClick={login}>Login</button>
        {error && <p style={{ color: "red" }}>{error}</p>}
      </div>
    );
  }

  if (user.role === "patient") {
    return (
      <div>
        <h1>Welcome {user.name}</h1>
        <p>Age: {user.age}</p>
        <p>Sex: {user.sex}</p>
        <h3>Heart Rate Records</h3>
        <ul>
          {user.heart_rates.map((r, i) => (
            <li key={i}>
              {r.timestamp}: {r.heart_rate}
            </li>
          ))}
        </ul>
      </div>
    );
  }
  if (user.role === "doctor") {
  return (
    <div style={{ padding: 20 }}>
      <h1>Doctor Dashboard: {user.name}</h1>
      {user.patients.map((p) => (
        <div key={p.key} style={{ marginBottom: 30, border: "1px solid #ccc", padding: 10 }}>
          <h2>{p.name}</h2>
          <p>
            <strong>Personal Information</strong><br />
            Age: {p.age} | Gender: {p.sex}<br />
            Heart Rate: {p.heart_rate || "-"}<br />
            Implements: None
          </p>
          <p>
            <strong>Heart Rate Range:</strong> {HARD_CODED_VALUES.heartRateRange}
          </p>
          <p>
            <strong>Exercise List:</strong><br />
            {HARD_CODED_VALUES.exerciseList.map((ex, i) => (
              <span key={i}>{ex}<br /></span>
            ))}
          </p>
          <p>
            <strong>Reps/Time:</strong><br />
            {HARD_CODED_VALUES.repsTime.map((r, i) => (
              <span key={i}>{r}<br /></span>
            ))}
          </p>
          <p>
            <strong>Weight/Intensity:</strong><br />
            {HARD_CODED_VALUES.weightIntensity.map((w, i) => (
              <span key={i}>{w}<br /></span>
            ))}
          </p>
        </div>
      ))}
    </div>
  );
}

  return null;
}

export default App;
